            switch (isOpen ? nextWindowId : prevWindowId)
            {
                case UIWindowID.CONTEXTMENU:
                case UIWindowID.KEYGUIDE:
                case UIWindowID.CONTEST_POKEMON:
                case UIWindowID.CONTEST_WAZA:
                case UIWindowID.CONTEST_CAPSULE:
