		public global::XLSXContent.UIDatabase.SheetZukanRating GetZukanRatingData(bool isZenkokuZukan) {
            int seeCount;
            int getCount;
            if (isZenkokuZukan)
            {
                seeCount = ZukanWork.SeeCount(true);
                getCount = ZukanWork.GetCount(true);
            }
            else
            {
                seeCount = ZukanWork.SeeSinouCount(true);
                getCount = ZukanWork.GetSinouCount(true);
            }

            // both flags are read unconditionally, GetSysFlag first (@017c1c8c / @017c1cb0)
            bool isArriveHakutai = FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.FLAG_ARRIVE_C04);
            bool isZenkoku = ZukanWork.GetZenkokuFlag();

            // the loop is unswitched four ways in the listing (isZenkokuZukan × (isArriveHakutai && !isZenkoku)); the last match wins
            UIDatabase.SheetZukanRating result = null;
            foreach (var rating in _mdUis.ZukanRating)
            {
                if (!isZenkokuZukan && rating.IsZenkokuZukan)
                    continue;

                if (isArriveHakutai && !isZenkoku)
                {
                    if (rating.OtherCondition == ZukanRatingConditionType.NOT_HAKUTAI_OR_ZENKOKU)
                        continue;
                }
                else if (rating.OtherCondition == ZukanRatingConditionType.HAKUTAI_AND_NOT_ZENKOKU)
                {
                    continue;
                }

                int count = rating.IsGetCount ? getCount : seeCount;
                if (count >= rating.RatingMinCount && count <= rating.RatingMaxCount)
                    result = rating;
            }

            return result;
        }
