		public void LoadSpritePokemonLarge(global::Pml.MonsNo monsNo, ushort formNo, global::Pml.Sex sex, global::Pml.PokePara.RareType rareType, bool isEgg, global::UnityEngine.Events.UnityAction<global::UnityEngine.Sprite> onComplete) {
            int uniqueId = GameData.DataManager.GetUniqueID(monsNo, formNo, sex, rareType, isEgg);
            CacheSpritePokemonParam cache = _cacheSpritePokemons.Find(x => x.uniqueId == uniqueId);
            if (cache == null)
            {
                string assetBundleName = Instance.GetPokemonIconData(monsNo, formNo, sex, rareType, isEgg).AssetBundleNameLarge;
                if (AssetManager.IsExistAssetBundle(assetBundleName))
                {
                    cache = new CacheSpritePokemonParam() { uniqueId = uniqueId };
                    _cacheSpritePokemons.Add(cache);
                    AssetManager.AppendAssetBundleRequest(assetBundleName, true, null, null);
                    AssetManager.DispatchRequests((RequestEventType requestEventType, string name, UnityEngine.Object content) =>
                    {
                        switch (requestEventType)
                        {
                            case RequestEventType.Activated:
                                var texture = content as Texture2D;
                                if (texture != null)
                                {
                                    var sprite = Sprite.Create(texture, new Rect(0f, 0f, texture.width, texture.height), Vector2.zero);
                                    cache.sprite = sprite;
                                    _cacheSpritePokemons.MoveLast(cache, null);
                                    onComplete.Invoke(sprite);
                                }
                                break;

                            case RequestEventType.Complete:
                                AssetManager.UnloadAssetBundle(assetBundleName);
                                break;
                        }
                    });
                    return;
                }

                onComplete.Invoke(null);
            }
            else
            {
                _cacheSpritePokemons.MoveLast(cache, x =>
                {
                    x.Destroy();
                    return true;
                });

                if (cache.sprite != null)
                    onComplete.Invoke(cache.sprite);
                else
                    Sequencer.Start(OpCompleteSprite<int>(cache, onComplete));
            }

            IEnumerator OpCompleteSprite<T>(CacheSpritePokemonParam cache_, UnityAction<Sprite> onComplete_)
            {
                while (cache_.sprite == null)
                    yield return null;

                onComplete_.Invoke(cache_.sprite);
            }
        }
