		internal void _CaptureBlueImage(bool enabled) {
            // @017ab0e0: the packet C names the static `STATIC_0x38(Graphics)`; the listing loads SmartPoint.Rendering.DepthOfField_TypeInfo
            // (+0x38 = DepthOfField.instance, +0x78 = blurredRT = the inlined `strongerBlurTexture` getter)
            if (SmartPoint.Rendering.DepthOfField.instance == null)
                return;

            var blurTexture = SmartPoint.Rendering.DepthOfField.instance.strongerBlurTexture;
            if (blurTexture == null)
                return;

            _blurBgParam.isCapture = enabled;
            if (!enabled)
                return;

            if (_blurBgParam.blankTexture == null)
            {
                var texture = new Texture2D(2, 2, TextureFormat.ARGB32, false);
                var color = new Color32(0, 0, 0, 1);
                texture.SetPixels32(new Color32[] { color, color, color, color }, 0);
                texture.Apply(false);
                _blurBgParam.blankTexture = texture;
            }

            // shipped: blits into `captureBlurTexture`, which nothing in UIManager ever assigns
            Graphics.Blit(blurTexture, _blurBgParam.captureBlurTexture);
        }
		private void UpdateBlurBg() {
            // IsActiveFadeBlur / SetActiveFadeBlur are flag-less and inlined here (@017c0ec0 / @017c1088)
            if (!IsActiveFadeBlur())
                return;

            if (_blurBgParam.isCapture)
            {
                _blurBg.texture = _blurBgParam.blankTexture;
            }
            else
            {
                var blurTexture = SmartPoint.Rendering.DepthOfField.instance != null ? SmartPoint.Rendering.DepthOfField.instance.strongerBlurTexture : null;
                if (blurTexture != null && _blurBg.texture != blurTexture)
                    _blurBg.texture = blurTexture;
            }

            if (float.IsNegativeInfinity(_blurBgParam.time))
                return;

            _blurBgParam.time += Time.deltaTime;
            float rate = _blurBgParam.time / _blurBgParam.maxTime;
            if (rate > 1.0f)
            {
                if (_blurBgParam.fadeType == BlugBgParam.FadeType.Out)
                {
                    _blurBgParam.isCapture = false;
                    SetActiveFadeBlur(false);
                }

                _blurBgParam.onComplete?.Invoke();
                _blurBgParam.onComplete = null;
                _blurBgParam.time = float.NegativeInfinity;
            }

            // the Lerp runs before `_blurBg` is loaded as the set_color receiver (@017c110c / @017c1110)
            float alpha = Mathf.Lerp(_blurBgParam.srcAlpha, _blurBgParam.destAlpha, rate);
            _blurBg.color = new Color(_blurBg.color.r, _blurBg.color.g, _blurBg.color.b, alpha);
        }
