		public static bool IsLumpingRibbon(int ribbonNo) {
            return ribbonNo == (int)RibbonNo.LUMPING_CONTEST || ribbonNo == (int)RibbonNo.LUMPING_TOWER;
        }
		public static int GetLumpingRibbonMaxNum(int ribbonNo) {
            if (!IsLumpingRibbon(ribbonNo))
                return 0;

            return ribbonNo == (int)RibbonNo.LUMPING_CONTEST ? 40 : 8;
        }
		public global::UnityEngine.Sprite GetSpriteRibbon(global::Pml.PokePara.PokemonParam pokemonParam, int ribbonNo) {
            string name;
            if (IsLumpingRibbon(ribbonNo))
            {
                uint num = pokemonParam.GetLumpingRibbon((uint)ribbonNo);
                name = string.Format("img_ribbon_{0:000}{1}", ribbonNo, num >= GetLumpingRibbonMaxNum(ribbonNo) ? "_b" : "_a");
            }
            else
            {
                name = string.Format("img_ribbon_{0:000}", ribbonNo);
            }
            return Instance.GetAtlasSprite(SpriteAtlasID.TEXTUREMASS, name);
        }
